// Builds the Actor input for global-corporate-patent-intelligence and cleans the watchlist exactly as the engine does.
// Edit CONFIG only. This template carries no credential: sources that need one are refused below, and a credential
// is never accepted inside sourceOptions (Apify only masks top-level secret input fields).
const CONFIG = {
    sources: ['clinicaltrials_orange_book', 'sg_acra'],
    deltaMode: 'onlyChanged',
    maxItemsPerSource: 100,
    watchlistNames: ['Acme Corp'],
    sourceOptions: {},
    stateNamespace: 'n8n-patents',
};

// Copied from distribution/python/src/regulatory_engines/data/engines.json; test/distribution_sync.test.ts fails when these lists drift from it.
const ACTIVE_SOURCES = ['uspto_ptab', 'epo_opposition', 'clinicaltrials_orange_book', 'sg_acra', 'ae_registers'];
const HELD_SOURCES = [];
const REQUIRED_OPTIONS = { uspto_ptab: ['usptoOdpApiKey'], epo_opposition: ['epoOpsConsumerKey', 'epoOpsConsumerSecret'] };
const CREDENTIAL_NAMES = ['epoopsconsumerkey', 'epoopsconsumersecret', 'fdaapikey', 'socrataapptoken', 'usptoodpapikey'];
const DELTA_MODES = ['all', 'onlyChanged', 'onlyNew'];

// --- watchlist guard: a port of lib/_guards.ts, identical in the three templates ---
const MIN_KEYWORD_LENGTH = 2;
const MAX_KEYWORD_LENGTH = 200;
const MAX_KEYWORDS = 500;
const MAX_RAW_KEYWORD_UNITS = 4096;
const MAX_CANDIDATES = 5000;
const MAX_BARE_STRING_UNITS = 200000;
const MAX_NORMALISE_PASSES = 8;
const MAX_TOTAL_RAW_UNITS = 200000;
const WHITESPACE_CONTROLS = /[\t\n\v\f\r\u0085\u2028\u2029]/gu;
const INVISIBLE = /[\u0000-\u001f\u007f-\u009f\p{Default_Ignorable_Code_Point}\p{Bidi_Control}]/gu;
const INVISIBLE_ONE = /[\u0000-\u001f\u007f-\u009f\p{Default_Ignorable_Code_Point}\p{Bidi_Control}]/u;
const WHITE_SPACE_ONE = /\p{White_Space}/u;
const WHITESPACE_RUN = /\s+/gu;
const LONE_SURROGATE = /\p{Surrogate}/u;
// MAX_COMBINING_RUN (16) + 1 consecutive combining marks: a text with such a run is empty (NFKC reorders marks, which is quadratic in the length of a run).
const COMBINING_RUN_TOO_LONG = /\p{M}{17}/u;
const HAS_LETTER_OR_DIGIT = /[\p{L}\p{N}]/u;
const BARE_STRING_SEPARATORS = /[\n\r,;]+/u;

function codePointLength(text) {
    return Array.from(text).length;
}

// Letters and digits in the text, counted up to atLeast (then it stops).
function countLettersOrDigits(text, atLeast) {
    let n = 0;
    for (const ch of text) {
        if (HAS_LETTER_OR_DIGIT.test(ch)) {
            n += 1;
            if (n >= atLeast) return n;
        }
    }
    return n;
}

// Code points that are neither invisible nor whitespace, counted up to atLeast: the glyphs a reader sees.
function countVisible(text, atLeast) {
    let n = 0;
    for (const ch of text) {
        if (INVISIBLE_ONE.test(ch) || WHITE_SPACE_ONE.test(ch)) continue;
        n += 1;
        if (n >= atLeast) return n;
    }
    return n;
}

function cleanOnce(text) {
    // Before normalize: reordering a long run of marks is quadratic, and no real text contains one.
    if (COMBINING_RUN_TOO_LONG.test(text)) return '';
    const normalised = text.normalize('NFKC');
    // No real text grows 4x under NFKC; one that does (U+FDFA becomes 18 characters) is made to burn the passes.
    if (normalised.length > text.length * 4 + 16) return '';
    return normalised.replace(WHITESPACE_CONTROLS, ' ').replace(INVISIBLE, '').replace(WHITESPACE_RUN, ' ').trim();
}

// Cleans until the text stops changing, so cleaning twice equals cleaning once (removing an invisible character can expose a sequence NFKC then composes).
// A text that has not settled after MAX_NORMALISE_PASSES passes is hostile and becomes '', which is never accepted.
function normaliseKeyword(raw) {
    let current = raw;
    for (let pass = 0; pass < MAX_NORMALISE_PASSES; pass += 1) {
        const next = cleanOnce(current);
        if (next === current) return next;
        current = next;
    }
    return '';
}

// The text cut to at most max UTF-16 units, without leaving half of a surrogate pair at the end.
function cutUnits(text, max) {
    if (text.length <= max) return text;
    const last = text.charCodeAt(max - 1);
    return text.slice(0, last >= 0xd800 && last <= 0xdbff ? max - 1 : max);
}

function sanitizeKeywordList(input) {
    try {
        return sanitizeUnchecked(input);
    } catch {
        // A value that cannot be read at all disables the watchlist, never the run.
        return { keywords: [], rejected: { not_a_string: 1 }, malformedContainer: true };
    }
}

function sanitizeUnchecked(input) {
    const result = { keywords: [], rejected: {}, malformedContainer: false };
    const reject = (reason) => {
        result.rejected[reason] = (result.rejected[reason] ?? 0) + 1;
    };
    if (input === undefined || input === null) return result;
    let candidates;
    let bareStringCut = false;
    if (Array.isArray(input)) {
        candidates = input;
    } else if (typeof input === 'string') {
        const window = cutUnits(input, MAX_BARE_STRING_UNITS);
        candidates = window.split(BARE_STRING_SEPARATORS);
        if (window.length < input.length) {
            // The cut may have truncated the last piece ("Pfizer Inc" -> "Pfizer In"), which would be accepted as a different keyword: drop it.
            candidates.pop();
            bareStringCut = true;
        }
    } else {
        result.malformedContainer = true;
        return result;
    }
    const seen = new Set();
    const limit = Math.min(candidates.length, MAX_CANDIDATES);
    let inspected = 0;
    let totalRawUnits = 0;
    for (let index = 0; index < limit; index += 1) {
        const candidate = candidates[index];
        // Only entries that proceed to Unicode work cost budget: one over the raw cap is rejected in constant time below.
        if (typeof candidate === 'string' && candidate.length <= MAX_RAW_KEYWORD_UNITS) {
            totalRawUnits += candidate.length;
            if (totalRawUnits > MAX_TOTAL_RAW_UNITS) break;
        }
        inspected += 1;
        if (typeof candidate !== 'string') {
            reject('not_a_string');
            continue;
        }
        if (candidate.length > MAX_RAW_KEYWORD_UNITS) {
            reject('too_long');
            continue;
        }
        if (LONE_SURROGATE.test(candidate)) {
            reject('invalid_unicode');
            continue;
        }
        const cleaned = normaliseKeyword(candidate);
        if (cleaned.length === 0) {
            reject('empty_after_normalisation');
            continue;
        }
        if (codePointLength(cleaned) < MIN_KEYWORD_LENGTH) {
            reject('too_short');
            continue;
        }
        // One glyph that NFKC expands (a circled number, the numero sign, a ligature) is one character typed, not two.
        if (countVisible(candidate, MIN_KEYWORD_LENGTH) < MIN_KEYWORD_LENGTH) {
            reject('too_short');
            continue;
        }
        const lettersOrDigits = countLettersOrDigits(cleaned, 2);
        if (lettersOrDigits === 0) {
            reject('no_letter_or_digit');
            continue;
        }
        // One letter or digit padded with punctuation ("c.", "a |", "-0") matches almost everything: the one-letter needle in disguise.
        if (lettersOrDigits === 1) {
            reject('single_letter_or_digit');
            continue;
        }
        if (codePointLength(cleaned) > MAX_KEYWORD_LENGTH) {
            reject('too_long');
            continue;
        }
        const needle = cleaned.toLowerCase();
        if (seen.has(needle)) {
            reject('duplicate');
            continue;
        }
        if (result.keywords.length >= MAX_KEYWORDS) {
            reject('over_limit');
            continue;
        }
        seen.add(needle);
        result.keywords.push(cleaned);
    }
    if (candidates.length > inspected) reject('over_limit');
    if (bareStringCut) reject('over_limit');
    return result;
}

function isSupplied(value) {
    try {
        if (value === undefined || value === null) return false;
        if (typeof value === 'string' || Array.isArray(value)) return value.length > 0;
        if (typeof value === 'object') return Object.keys(value).length > 0;
        return true;
    } catch {
        return true;
    }
}
// --- end watchlist guard ---

function fail(message) {
    throw new Error(`Refused before any run started, nothing was billed: ${message}`);
}

function containsCredentialKey(value) {
    if (Array.isArray(value)) return value.some(containsCredentialKey);
    if (value !== null && typeof value === 'object') {
        return Object.entries(value).some(([key, item]) => CREDENTIAL_NAMES.includes(key.toLowerCase()) || containsCredentialKey(item));
    }
    return false;
}

if (!Array.isArray(CONFIG.sources) || CONFIG.sources.length === 0 || CONFIG.sources.some((id) => typeof id !== 'string' || id.trim() === '')) {
    fail('CONFIG.sources must be a non-empty list of source id strings.');
}
const sources = [...new Set(CONFIG.sources.map((id) => id.trim().toLowerCase()))];
for (const id of sources) {
    if (HELD_SOURCES.includes(id)) fail(`source "${id}" is held: it is registered but refused by the engine.`);
    if (!ACTIVE_SOURCES.includes(id)) fail(`unknown source "${id}". Active sources: ${ACTIVE_SOURCES.join(', ')}.`);
}
if (!DELTA_MODES.includes(CONFIG.deltaMode)) fail(`deltaMode must be one of ${DELTA_MODES.join(', ')}.`);
if (!Number.isInteger(CONFIG.maxItemsPerSource) || CONFIG.maxItemsPerSource < 1 || CONFIG.maxItemsPerSource > 10000) fail('maxItemsPerSource must be an integer from 1 to 10000.');
if (CONFIG.stateNamespace !== undefined && CONFIG.stateNamespace !== '' && !/^[a-z0-9-]{1,40}$/u.test(CONFIG.stateNamespace)) fail('stateNamespace must be 1-40 characters of a-z, 0-9 and "-".');
if (containsCredentialKey(CONFIG.sourceOptions)) fail('sourceOptions must not contain a credential; this template cannot carry one.');
const optionsBySource = new Map();
for (const [id, value] of Object.entries(CONFIG.sourceOptions ?? {})) {
    const key = id.trim().toLowerCase();
    if (!sources.includes(key)) fail(`sourceOptions has an entry for "${id}", which is not a selected source.`);
    if (optionsBySource.has(key)) fail(`sourceOptions has two entries for "${key}".`);
    if (value === null || typeof value !== 'object' || Array.isArray(value)) fail(`sourceOptions["${id}"] must be an object.`);
    if (Object.keys(value).length > 0) optionsBySource.set(key, value);
}
for (const id of sources) {
    const given = optionsBySource.get(id) ?? {};
    const missing = (REQUIRED_OPTIONS[id] ?? []).filter((name) => given[name] === undefined || given[name] === null || (typeof given[name] === 'string' && given[name].trim() === ''));
    if (missing.length > 0) fail(`source "${id}" requires ${missing.join(', ')}, which this template cannot supply (credentials are never placed in sourceOptions).`);
}

const incoming = $input.first()?.json ?? {};
const rawWatchlist = incoming.watchlistNames !== undefined ? incoming.watchlistNames : CONFIG.watchlistNames;
const watchlist = sanitizeKeywordList(rawWatchlist);
const rejectedCount = Object.values(watchlist.rejected).reduce((sum, count) => sum + count, 0);
if (isSupplied(rawWatchlist) && watchlist.keywords.length === 0) {
    fail(`the watchlist was supplied but none of it is usable (${watchlist.malformedContainer ? 'unsupported value type' : `${rejectedCount} entries rejected`}); refusing to run unfiltered.`);
}

const input = { sources, deltaMode: CONFIG.deltaMode, maxItemsPerSource: CONFIG.maxItemsPerSource };
if (optionsBySource.size > 0) input.sourceOptions = Object.fromEntries(optionsBySource);
if (watchlist.keywords.length > 0) input.watchlistNames = watchlist.keywords;
if (CONFIG.stateNamespace) input.stateNamespace = CONFIG.stateNamespace;

return [{ json: { input, watchlist: { accepted: watchlist.keywords.length, rejected: rejectedCount, rejectedByReason: watchlist.rejected } } }];
